'use strict';
const $=id=>document.getElementById(id),sound=new DmiSound();let frame=null,token='',busy=false;
const incoming=new URLSearchParams(location.hash.slice(1)).get('token');if(incoming&&/^[a-f0-9]{32}$/.test(incoming)){token=incoming;CTCS.api.controlToken=token;try{sessionStorage.setItem('dmi-control-token',token)}catch{};history.replaceState(null,'',location.pathname)}
$('brake').oninput=()=>$('brake-value').textContent=$('brake').value+'%';
function buttons(){for(let id of ['apply','release','emergency'])$(id).disabled=(id!=='emergency'&&frame?.Mapping?.armed)||busy||!token||!frame?.Fresh||!frame?.Brake?.ready||frame?.GameAdvancing===false}
async function command(percent,emergency=false){if(busy)return;busy=true;buttons();try{sound.unlock();let j=await CTCS.api.post('/api/brake',{percent,emergency,vehicle:frame.Vehicle},true,true);$('command-result').textContent=(emergency?'紧急制动':percent===0?'缓解／空挡':'常用制动 '+percent+'%')+'：'+j.message;sound.play('S_click')}catch(e){$('command-result').textContent=e.message}finally{busy=false;buttons()}}
$('apply').onclick=()=>command(Number($('brake').value));$('release').onclick=()=>command(0);$('emergency').onclick=()=>command(100,true);
async function poll(){let received=false;try{frame=await CTCS.api.get('/api/frame');received=true;token=CTCS.api.token||CTCS.api.controlToken;$('control-status').textContent=!token?'正在自动建立操纵连接，请稍候':!frame.Fresh?'等待 TSW 有效数据':!frame.DmiReady?(frame.CabActivation?.reason||'等待司机室激活'):frame.GameAdvancing===false?'游戏时间未推进 · 请先恢复游戏':frame.Brake?.supported?'TSW 已连接 · 制动输入可用':'游戏尚未提供可识别的操纵控件';$('operation-state').textContent=(frame.Operations?.message||'等待司机室激活')+' · '+(frame.Operations?.elapsed||0)+' s / '+(frame.Operations?.distance||0)+' m';$('station-info').textContent=DmiMapping.station(frame);$('mapping-info').textContent=(frame.Supervision?.system||'AUTO')+' · '+(frame.Supervision?.source||'等待限速')+'\n'+(frame.Mapping?.message||'未启用摇杆');$('vehicle').textContent=frame.Vehicle||'';let n=x=>Number.isFinite(x)?x.toFixed(2):'—',output=frame.Brake?.output;let notch=!Number.isFinite(output)?'—':frame.Brake?.emergency?'紧急制动 ('+output+')':frame.Brake?.service?'制动 ('+output+')':'输出 '+output;$('feedback').textContent='实际档位 '+notch+' · 速度 '+n(frame.Speed)+' km/h · 加速度 '+n(frame.Acceleration)+' m/s² · 手柄输入 '+n(frame.Brake?.input)}catch(e){if(!received)frame=null;$('control-status').textContent=received?'页面显示异常（桥接已连接）':'桥接已断开，正在重试';$('feedback').textContent=e.message||'数据失效'}buttons();setTimeout(poll,400)}
CTCS.api.init().then(()=>{token=CTCS.api.token||CTCS.api.controlToken}).catch(e=>{$('control-status').textContent=e.message}).finally(poll);

for(let [id,action]of [['vigilance-op','vigilance'],['release-op','release'],['braketest-op','braketest']])$(id).onclick=async()=>{try{let r=await CTCS.api.operation({action,vehicle:frame?.Vehicle});$('operation-result').textContent=r.message}catch(e){$('operation-result').textContent=e.message}};
